package org.stellarproximology.trident;
import android.content.*;import android.provider.Settings;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;
public final class LocalBridgeServer{private final Context c;private final int port;private volatile ServerSocket s;private final ExecutorService pool=Executors.newCachedThreadPool();LocalBridgeServer(Context c,int p){this.c=c;port=p;}void start(){if(s!=null)return;pool.submit(()->{try{s=new ServerSocket(port,8,InetAddress.getByName("127.0.0.1"));while(!s.isClosed()){Socket x=s.accept();pool.submit(()->handle(x));}}catch(Exception ignored){}});}void stop(){try{if(s!=null)s.close();}catch(Exception ignored){}s=null;pool.shutdownNow();}
 private void handle(Socket x){try(Socket q=x;BufferedReader r=new BufferedReader(new InputStreamReader(q.getInputStream(),StandardCharsets.UTF_8));OutputStream out=q.getOutputStream()){String first=r.readLine();if(first==null)return;String[]p=first.split(" ");int len=0;String l;while((l=r.readLine())!=null&&!l.isEmpty())if(l.toLowerCase().startsWith("content-length:"))len=Integer.parseInt(l.substring(15).trim());char[]buf=new char[len];int n=0;while(n<len){int z=r.read(buf,n,len-n);if(z<0)break;n+=z;}JSONObject b=len>0?new JSONObject(new String(buf,0,n)):new JSONObject();JSONObject res=dispatch(p[0],p[1],b);byte[]data=res.toString().getBytes(StandardCharsets.UTF_8);String h="HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nAccess-Control-Allow-Origin: *\r\nContent-Length: "+data.length+"\r\nConnection: close\r\n\r\n";out.write(h.getBytes(StandardCharsets.UTF_8));out.write(data);}catch(Exception ignored){}}
 private JSONObject dispatch(String m,String p,JSONObject b)throws Exception{TridentAccessibilityService h=TridentAccessibilityService.getInstance();if("/status".equals(p))return new JSONObject().put("ok",true).put("bridge","trident-android-hands").put("accessibilityEnabled",h!=null).put("overlayAllowed",Settings.canDrawOverlays(c)).put("linuxLayer","pending-bootstrap");if(h==null)return new JSONObject().put("ok",false).put("error","Enable Trident Hands in Accessibility settings");if("/screen".equals(p))return h.snapshot();boolean a=false;if("/tap".equals(p))a=h.tap((float)b.getDouble("x"),(float)b.getDouble("y"));else if("/swipe".equals(p))a=h.swipe((float)b.getDouble("x1"),(float)b.getDouble("y1"),(float)b.getDouble("x2"),(float)b.getDouble("y2"),b.optLong("durationMs",350));else if("/click-text".equals(p))a=h.clickText(b.optString("text"));else if("/set-text".equals(p))a=h.setText(b.optString("text"));else if("/global".equals(p))a=h.global(b.optString("action"));return new JSONObject().put("ok",a).put("accepted",a);}
}